// th14_s5_w11 TH14 Stage 5 道中波
// 源：st05.ecl.txt::MainSub06 871-944（entry）；ECir00 14-47、ECir00_at 49-81（本卡闭包）。
// 卡帧 0 起段计时，120 帧开场缓冲后从源 871 行进入六批 ECir00（6/6/10/6/6/10）。

const TIME_LIMIT: int = 1724;
const OPENING_BUFFER: int = 120;

// 源 etSprite(0, 10, 6)：TH14 type10 对应目标同号槽，颜色 6。
const TH14_SHARD: int = 512;
const BULLET_COLOR: int = 6;

// 源 0.17453292 rad（10°）的 BAM 步长；用于扇形路间距与每波 ±10° 中轴抖动。
const TURN_10DEG: int = 1820;
// 源 ACCEL r = 0.033333335 px/帧²。
const ACCEL_MAG: fx = 0.033333fx;

// ECir00_at 的 etEx(0, 0, 4, 120, -999999, 0.033333335, %F2-π)：
// 效果进入取固定角 s=%F2-π，沿该方向按 r 加速，持续 120 帧后清零。
xformdef ARC_ACCEL(adir: angle) {
    @120 set_gravity(cos(adir) * ACCEL_MAG, sin(adir) * ACCEL_MAG);
    set_gravity(0fx, 0fx);
}

// ECir00_at：wait(10) 后一次 etOn；$I0=1 ⇒ if ($B--) 只执行一遍发射。
async sub fire_fan(dir: angle) {
    wait(10);
    var n: int = 1;
    var rank: int = global(GVAR_RANK);
    if rank == 1 { n = 3; }
    if rank == 2 { n = 5; }
    if rank == 3 { n = 7; }
    // 源 etAngle(0, %F2 + RANDF2*10°, 10°)：每波抽一次 ±10° 中轴抖动。
    var jitter: int = rand(3641) - TURN_10DEG;
    var base: angle = dir + (jitter as angle);
    var i: int = 0;
    while i < n {
        // 源 mode1 固定方向扇形 F(N,i)：0, -d, +d, -2d, +2d, ...
        var off: int = ((i + 1) / 2) * TURN_10DEG;
        if i % 2 != 0 { off = 0 - off; }
        _ = fire(TH14_SHARD, BULLET_COLOR, $self_x, $self_y, 2fx,
                 base + (off as angle), ARC_ACCEL(dir + 180deg), none);
        i = i + 1;
    }
}

// ECir00 主任务：父敌在 (160+RANDF2*32, y0+RANDF2*64) 出生，
// 再用 movePosRelTime(160, 1, F0, F1) 的 mode1(t²) 到相对目标 (F0, F1)。
async sub ecir00(y0: fx, f0: fx, f1: fx, dir: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);   // 源 setHurtbox(24,24)：普通圆取第一值×0.5
    set_hitbox(8fx);     // 源 setHitbox(16,16)：普通圆取第一值×0.5
    move_to(160, f0, y0 + f1, EASE_QUAD_IN);
    wait(160);
    spawn fire_fan(dir);
    wait(120);
    // 源 moveVel(%ANGLE_PLAYER, 0) + moveSpeedTime(120, 0, 3.0)
    move_vel(0, atan2($player_y - $self_y, $player_x - $self_x), 0fx, EASE_LINEAR);
    move_speed(120, 3fx, EASE_LINEAR);
    loop { wait(1000); }
}

// MainSub06 871-944 的一批：先改 F0 与随机 F1，再按当前 F2 创建；命中计数 $E-- 共 count 次。
sub spawn_batch(count: int, y0: fx, f0start: fx, f0step: fx, f1base: fx, gap: int, flip: int) {
    var f0: fx = f0start;
    var dir: angle = 270deg;   // %F2 = -1.570796（朝上）
    var i: int = 0;
    while i < count {
        f0 = f0 + f0step;
        // %F1 = (%RANDF2 * 32) + base
        var f1: fx = f1base + ((rand(4097) as fx - 2048fx) / 64fx);
        // movePosRel(_f(160) + RANDF2*32, RANDF2*64)
        var rx: fx = (rand(4097) as fx - 2048fx) / 64fx;
        var ry: fx = (rand(8193) as fx - 4096fx) / 64fx;
        _ = spawn_enemy(160fx + rx, y0 + ry, 160, 0, 0, 0, ecir00(y0, f0, f1, dir));
        if flip != 0 { dir = 0deg - dir; }   // %F2 = %F2 * -1（第三/六批逐只翻）
        wait(gap);
        i = i + 1;
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    spawn_batch(6, 200fx, 160fx, -32fx, -128fx, 3, 0);
    wait(50);
    spawn_batch(6, 240fx, -160fx, 32fx, -96fx, 3, 0);
    wait(50);
    spawn_batch(10, 280fx, -160fx, 32fx, -32fx, 7, 1);
    wait(50);
    spawn_batch(6, 200fx, 160fx, -32fx, -128fx, 3, 0);
    wait(50);
    spawn_batch(6, 140fx, -160fx, 32fx, -160fx, 3, 0);
    wait(50);
    spawn_batch(10, 320fx, -160fx, 32fx, 0fx, 7, 1);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
